import{_ as a,o as t,c as r,ag as s}from"./chunks/framework.2cFhd8Ux.js";const c=JSON.parse('{"title":"Week 12 — Evals","description":"","frontmatter":{"source":"weeks/12-evals/README.md"},"headers":[],"relativePath":"weeks/12-evals/index.md","filePath":"weeks/12-evals/index.md"}'),n={name:"weeks/12-evals/index.md"};function o(i,e,l,d,h,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="week-12--evals" tabindex="-1">Week 12 — Evals <a class="header-anchor" href="#week-12--evals" aria-label="Permalink to &quot;Week 12 — Evals&quot;">​</a></h1><blockquote><p>An eval is a measuring instrument, and so is an LLM judge: before you trust a number from either, measure the instrument against human labels and say how uncertain it is.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>The reading and your reading response · submit the week 11 assignment (the Seminar opens with its quiz) · CS [5xxx]: interim results are due before this Seminar · if a graduate paper is presented, post one question (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz · talk: eval design, LLM-as-judge pitfalls and calibration, regression evals in CI, benchmarks and their limits (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-12.html" target="_blank" rel="noreferrer">slides</a>) · benchmark-case jigsaw or a graduate paper · demo · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--calibrate-the-judge-then-gate-ci-75-min">Calibrate the judge, then gate CI</a>: label titles blind, calibrate the judge, wire <code>eval:check</code> into CI. <strong>Checkoff:</strong> a calibration report with agreement and κ for the judge and the always-pass baseline</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--an-eval-report">assignment</a>, an eval report in <code>EVAL_PLAN.md</code>: what you measure and why, the eval set, judge calibration, thresholds, what the gate catches and misses</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: scripts and CI configuration · 🟡 AI limited: new eval cases (an AI may suggest inputs; you write every expected value) and the report&#39;s tables · 🔴 AI off: your labels, the quiz, the reading response</td></tr><tr><td><strong>Reading</strong></td><td>Hamel Husain, &quot;Using LLM-as-a-Judge For Evaluation: A Complete Guide&quot; (<a href="#reading">below</a>)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words, 🔴 AI off, on Canvas, before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td><strong>M2</strong> and peer evaluation 2 are due before the week 13 Seminar (<a href="./../../project/milestones.html#m2-major-contribution">milestones</a>); if your contribution uses an LLM, M2 includes this week&#39;s method in <code>course/EVAL_PLAN.md</code>. Optional upstream PRs may start (<a href="./../../project/contribution-rules.html#optional-upstream-prs-tier-3">rules</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td>This week&#39;s seminar papers: Shankar et al. (criteria drift), Wang, Pradel &amp; Liu (PatchDiff), Liang et al. (the SWE-bench illusion), Zhu et al. (the benchmark checklist) (<a href="./../../graduate/paper-presentations.html">paper presentations</a>). The critique is due before the week 13 Seminar (<a href="./../../graduate/#the-critique">graduate</a>)</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h)</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Design an <a href="./../../resources/glossary.html#eval">eval</a> from failure modes: cases, metrics, a dev and a held-out split, error bars, and a paired comparison between versions.</li><li>Explain why percent agreement flatters an <a href="./../../resources/glossary.html#llm-as-judge">LLM judge</a>, and compute and interpret <a href="./../../resources/glossary.html#cohens-kappa-κ">Cohen&#39;s κ</a> next to an always-pass baseline.</li><li>Calibrate a judge against your own blind labels, reporting n, agreement, κ and how well it catches failures, with human–human agreement as the ceiling.</li><li>Gate CI on <a href="./../../resources/glossary.html#recorded-responses">recorded responses</a>, set thresholds from a run, and say what the gate catches and what it misses.</li><li>Question a benchmark claim: harness, what &quot;pass&quot; means, contamination, reliability and error bars.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On your week 11 error analysis and improvement, 🔴 AI off (<a href="./../../assessment/quizzes.html">quizzes</a>)</td></tr><tr><td>Concept talk</td><td>25</td><td>Eval design; judges and their pitfalls; κ; calibration; regression evals in CI; benchmarks and their limits (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-12.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Jigsaw or paper</td><td>20</td><td>Benchmark cases D2–D5 (<a href="./../../resources/case-studies.html#benchmark-inflation">case studies</a>), or a graduate presentation</td></tr><tr><td>Live demo</td><td>10</td><td>An always-pass judge scores well on agreement and zero on κ; a &quot;harmless&quot; change passes the unit tests and fails the eval gate</td></tr><tr><td>Lab preview</td><td>5</td><td>Label before you look; which recordings your CI replays; the checkoff</td></tr></tbody></table><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html">lab</a> continues in your <code>eswa-eval-harness</code> repository. The kit&#39;s judge grades the free-text booking title against a three-point rubric. You label the 29 shipped titles yourself before seeing any verdict, then calibrate: the shipped judge agrees with human labels about 79% of the time, which sounds good until a judge that always says &quot;pass&quot; scores about 76%. Its κ is about 0.3; the baseline&#39;s is 0. Then you copy the kit&#39;s CI workflow, so every push replays the recordings and fails when a metric drops below its threshold, with no key and no cost.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Hamel Husain, <a href="https://hamel.dev/blog/posts/llm-judge/" target="_blank" rel="noreferrer">&quot;Using LLM-as-a-Judge For Evaluation: A Complete Guide&quot;</a></strong> (revised 2026), the reading list&#39;s <a href="./../../resources/reading-list.html#week-12--evals-and-benchmarks">core pick</a>. A practitioner&#39;s method: one domain expert gives binary pass/fail grades with a written critique, the judge prompt is iterated until it agrees with that expert, plan on about 100 labels per failure mode, and report true-positive and true-negative rates, because an always-&quot;pass&quot; judge agrees 95% of the time when 5% of outputs fail.</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off, on Canvas): The kit ships 29 human labels from one labeler, for one field. Using Husain&#39;s guide, say what a κ computed on those 29 items can tell you and what it can&#39;t. Name one step of his process that the kit&#39;s setup lacks, and how you would add it in this week&#39;s assignment. Then say whether you would let the shipped judge&#39;s verdict decide anything automatically, and why. End with one question for the Seminar.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>An eval is an experiment:</strong> a sample of cases, a metric, error bars and a decision rule. <strong>Capability</strong> evals ask what a system can do; <strong>regression</strong> evals check that it still does what it did. Grade outcomes, not step sequences (<a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">Anthropic</a>).</li><li><strong>Start from failure modes,</strong> found by reading outputs. Grading outputs changes your criteria, and some appear only after you look (<a href="./../../resources/glossary.html#criteria-drift">criteria drift</a>).</li><li><strong>Agreement flatters a judge when most outputs pass.</strong> κ = (observed agreement − chance agreement) / (1 − chance agreement): 1 is perfect, 0 is chance. Among 13 judges in one study, only the largest approached humans, and high agreement hid large score gaps (<a href="https://arxiv.org/abs/2406.12624" target="_blank" rel="noreferrer">Thakur et al.</a>).</li><li><strong>Calibrate on blind labels, and report n.</strong> Label before you see the judge&#39;s verdicts; report agreement, κ, the always-pass baseline, and how many failures the judge catches. On 29 items, κ is very uncertain. Two humans&#39; agreement on the same rubric is roughly the ceiling for any judge.</li><li><strong>A judge reads untrusted text too,</strong> and some checks (is the title plain text?) belong in code.</li><li><strong>A regression gate on recordings is cheap and narrow.</strong> It catches changes to the code after the model call (parsing, validation, repair, scoring). It can&#39;t see a provider updating its model, or inputs unlike your cases; a prompt change forces new recordings, in their own reviewed PR.</li><li><strong>A threshold is a target.</strong> For every gated metric, ask what change would raise it and whether that change makes the feature better.</li><li><strong>Benchmarks overstate.</strong> Filtering leaked solutions and weak tests cut a resolve rate from 12.47% to 3.97% (<a href="https://arxiv.org/abs/2410.06992" target="_blank" rel="noreferrer">SWE-Bench+</a>); models named the buggy file from the issue alone 76% of the time on SWE-bench, 53% elsewhere (<a href="https://arxiv.org/abs/2506.12286" target="_blank" rel="noreferrer">Liang et al.</a>, <a href="./../../resources/glossary.html#benchmark-contamination">contamination</a>); maintainers merged 24.2 points fewer than the grader accepted (<a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">METR</a>).</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>95% of titles truly pass. What agreement and what κ does an always-pass judge get, and why?</li><li>Your judge has κ 0.30 on 29 labels from one person. Write the sentence you&#39;d put in a report.</li><li>Your CI gate is green, and the provider has just updated the model behind your model ID. What did the gate check, and what didn&#39;t it?</li><li>Why must labels be made before you look at the judge&#39;s verdicts?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>No network or no key:</strong> labeling, calibration and the CI gate all replay recordings. Only the judge change in the assignment needs live calls; use the lab machine, where a small model makes a cheap judge (<a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a>).</li><li><strong>GitHub Actions is down or out of minutes:</strong> standard runners are free on public repositories (<a href="./../../resources/troubleshooting.html#ci-minutes-and-failing-workflows">troubleshooting</a>). Meanwhile run <code>npm run eval:check</code> locally and keep its output; push when Actions is back.</li><li><strong>Codespaces down:</strong> the kit runs on any laptop with Node 22 (<a href="./../../setup/sandboxes.html#dev-containers-on-your-laptop">sandboxes</a>).</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Shankar et al., <a href="https://arxiv.org/abs/2404.12272" target="_blank" rel="noreferrer">&quot;Who Validates the Validators?&quot;</a> (UIST 2024), the source of criteria drift; Wang, Guo, Gao et al., <a href="https://arxiv.org/abs/2502.06193" target="_blank" rel="noreferrer">&quot;Can LLMs Replace Human Evaluators?&quot;</a> (ISSTA 2025), judges for code.</li><li>Miller, <a href="https://arxiv.org/abs/2411.00640" target="_blank" rel="noreferrer">&quot;Adding Error Bars to Evals&quot;</a>: standard errors, paired comparisons and how many cases you need.</li><li>CS [5xxx]: Thakur et al. and Liang et al. are on the <a href="./../../resources/reading-list.html#replicable-studies">replicable list</a>.</li><li>Previous week: <a href="./../11-llm-features/">Building LLM Features</a>. Next week: <a href="./../13-parallel-agents/">Parallel and Background Agents</a>.</li></ul>',22)])])}const m=a(n,[["render",o]]);export{c as __pageData,m as default};
